            reads.insert(key);
        }
    }

    // Recurse into children (skip assignment children we already handled).
    if node.kind() != "assignment" {
        let count = node.child_count();
        for i in 0..count {
            if let Some(child) = node.child(i) {
                Self::collect_field_accesses(child, source, writes, reads);
